        const attemptFor=order=>{const raw=sql(`select coalesce((select jsonb_build_object('id',id,'result',attempt_result,'lifecycle',lifecycle,'version',version,'context',stream_result_context_digest,'recordedAt',stream_result_at,'claimedAt',claimed_at,'quotaBefore',quota_before,'quotaAfter',quota_after) from local_commerce.digital_delivery_attempts where order_id='${order.orderId}' order by created_at desc limit 1),'null'::jsonb);`);return JSON.parse(raw);};
